import json

# Load the JSON data
with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# Look for table metadata or year information
def find_table_info(d, path=""):
    if isinstance(d, dict):
        for k, v in d.items():
            if k in ['year', 'Year', 'period', 'Period', 'title', 'Title', 'description']:
                print(f"{path}.{k}: {v}")
            find_table_info(v, f"{path}.{k}")
    elif isinstance(d, list) and len(d) > 0:
        find_table_info(d[0], f"{path}[0]")

# Find the table with bond yields
for elem in data.get('document', {}).get('elements', []):
    if elem.get('type') == 'text' and 'yield' in elem.get('content', '').lower():
        print(elem.get('content', '')[:200])
